components.css:
.ds-btn-primary { background: var(--green); color: var(--white); border: 1px solid var(--green); border-radius: 4px; padding: 11px 15px; min-height: 46px; font: 400 14px/1.6 var(--sans); text-align: center; transition: background-color 160ms ease-out, color 160ms ease-out; }
.ds-btn-primary:hover { background: #173e33; }
.ds-btn-primary:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-btn-secondary { background: var(--white); color: var(--green); border: 1px solid var(--line); border-radius: 4px; padding: 10px 15px; min-height: 46px; font: 400 14px/1.6 var(--sans); }
.ds-btn-secondary:hover { background: var(--light); border-color: var(--green); }
.ds-btn-secondary:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-quiet-link { display: inline-flex; align-items: center; min-height: 44px; padding: 10px 0; color: var(--green); font: 400 14px/1.6 var(--sans); text-underline-offset: 5px; text-decoration-thickness: 1px; }
.ds-quiet-link:hover { text-decoration-thickness: 2px; }
.ds-quiet-link:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-search-field { display: block; color: var(--ink); font: 400 14px/1.8 var(--sans); }
.ds-search-input { display: block; width: 100%; min-width: 0; min-height: 46px; margin-top: 6px; padding: 10px 12px; border: 1px solid #91aab3; border-radius: 4px; background: var(--white); color: var(--ink); font: 400 16px/1.8 var(--sans); }
.ds-search-input::placeholder { color: #60757b; opacity: 1; }
.ds-search-input:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-nav-link { display: flex; align-items: center; min-height: 52px; padding: 12px 16px; border: 1px solid transparent; border-radius: 6px; color: var(--nav-muted); font: 400 16px/1.8 var(--sans); text-decoration: none; transition: background-color 160ms ease-out, color 160ms ease-out; }
.ds-nav-link:hover { background: #1a5060; color: var(--white); }
.ds-nav-link[aria-current=page] { background: #d9ecf1; color: var(--nav); font-weight: 700; }
.ds-nav-link:focus-visible { outline: 3px solid #ffc287; outline-offset: 4px; }

.ds-version { display: grid; grid-template-columns: 1fr auto; align-items: baseline; gap: 2px 8px; min-width: 0; padding: 12px 16px; border: 0; border-bottom: 3px solid transparent; background: transparent; color: var(--ink); text-align: left; font: 400 16px/1.8 var(--sans); }
.ds-version strong { font-size: 23px; font-weight: 650; font-variant-numeric: tabular-nums; }
.ds-version small { grid-row: 2; color: var(--muted); font-size: 13px; }
.ds-version[aria-pressed=true] { background: var(--light); border-bottom-color: var(--green); color: var(--green); }
.ds-version:hover { background: #eaf2f5; }
.ds-version:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-filter { min-height: 44px; padding: 8px 14px; border: 1px solid var(--line); border-radius: 4px; background: var(--white); color: var(--green); font: 400 14px/1.6 var(--sans); }
.ds-filter:hover { border-color: var(--green); }
.ds-filter[aria-pressed=true] { border-color: var(--green); background: var(--green); color: var(--white); }
.ds-filter:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-point-row { display: flex; align-items: flex-start; gap: 8px; padding: 10px 0; border-bottom: 1px solid var(--line); color: var(--ink); font: 400 14px/1.7 var(--sans); }
.ds-row-index { min-width: 20px; padding-top: 6px; color: var(--muted); font-size: 12px; font-variant-numeric: tabular-nums; }
.ds-point-button { flex: 1; min-width: 0; min-height: 44px; padding: 4px 0; border: 0; background: transparent; color: var(--ink); text-align: left; }
.ds-point-button strong, .ds-point-button small { display: block; }
.ds-point-button small { margin-top: 4px; color: var(--muted); font-size: 12px; }
.ds-point-button:hover { text-decoration: underline; text-underline-offset: 4px; }
.ds-point-button:focus-visible { outline: 3px solid var(--focus); outline-offset: 4px; }

.ds-limit-note { padding: 12px 16px; background: var(--warning); color: #734917; font: 400 14px/1.8 var(--sans); }
.ds-limit-note strong { display: block; }
.ds-limit-note p { margin: 6px 0 0; }
